with data as (select $j$[{"n":"Poulet au citron et thym, haricots verts","t":25,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Haricots verts",300,"g"],["Citron",1,"pièce"],["Thym"],["Ail"]],"e":"Cuire les haricots verts 8 min à l'eau bouillante.\nDorer le poulet 5 min par face avec l'ail et le thym.\nDéglacer avec le jus du citron et servir."},{"n":"Brochettes de poulet yakitori, riz et courgette","t":30,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Riz basmati",150,"g"],["Courgette",1,"pièce"],["Sauce soja"],["Miel"],["Graines de sésame"]],"e":"Mariner le poulet en cubes 10 min dans la sauce soja et un peu de miel.\nCuire le riz.\nGriller les brochettes et la courgette en rondelles 10 min.\nParsemer de sésame."},{"n":"Poulet coco curry, riz et épinards","t":30,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Lait de coco",0.5,"boîte"],["Riz basmati",150,"g"],["Oignon",1,"pièce"],["Épinards frais",100,"g"],["Curry"]],"e":"Faire revenir l'oignon et le poulet en dés avec le curry.\nAjouter le lait de coco, mijoter 12 min.\nAjouter les épinards à la fin.\nServir avec le riz."},{"n":"Cuisses de poulet rôties, carottes et pommes de terre","t":50,"g":["volaille","healthy"],"i":[["Cuisses de poulet",2,"pièce"],["Carottes",3,"pièce"],["Pommes de terre",3,"pièce"],["Herbes de Provence"]],"e":"Préchauffer le four à 200 °C.\nDisposer les cuisses et les légumes en morceaux dans un plat avec herbes et un filet d'huile.\nCuire 45 min en retournant à mi-cuisson."},{"n":"Salade César légère au poulet","t":20,"g":["volaille","healthy","rapide"],"i":[["Escalopes de poulet",250,"g"],["Salade romaine",1,"pièce"],["Parmesan",30,"g"],["Pain complet",2,"tranche"],["Yaourt grec",1,"pot"],["Citron",1,"pièce"]],"e":"Cuire le poulet et le couper en lanières.\nGriller le pain et le couper en croûtons.\nMélanger le yaourt, le citron et la moitié du parmesan pour la sauce.\nAssembler avec la salade."},{"n":"Poulet teriyaki et brocoli","t":25,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Brocoli",1,"pièce"],["Riz basmati",150,"g"],["Sauce soja"],["Miel"],["Gingembre"]],"e":"Cuire le riz et le brocoli à la vapeur 6 min.\nSaisir le poulet en lanières 6 min.\nAjouter 3 c. à s. de sauce soja, 1 de miel et le gingembre, laisser caraméliser 2 min."},{"n":"Blanquette de poulet légère","t":40,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Carottes",2,"pièce"],["Champignons",150,"g"],["Crème légère",100,"mL"],["Riz basmati",150,"g"],["Bouillon cube",1,"pièce"],["Oignon",1,"pièce"]],"e":"Faire revenir le poulet en morceaux et l'oignon.\nCouvrir d'eau avec le bouillon, ajouter les carottes en rondelles, cuire 20 min.\nAjouter les champignons 10 min, puis la crème.\nServir avec le riz."},{"n":"Poulet à la moutarde, courgettes et Ebly","t":25,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Courgettes",2,"pièce"],["Crème légère",100,"mL"],["Ebly",150,"g"],["Moutarde"]],"e":"Cuire l'Ebly.\nDorer le poulet, ajouter les courgettes en dés, cuire 8 min.\nAjouter la crème et 1 c. à s. de moutarde, laisser réduire 2 min."},{"n":"Wok de poulet aux légumes et nouilles","t":20,"g":["volaille","healthy","rapide"],"i":[["Escalopes de poulet",300,"g"],["Nouilles de riz",150,"g"],["Poivron",1,"pièce"],["Carottes",2,"pièce"],["Sauce soja"]],"e":"Réhydrater les nouilles.\nSaisir le poulet en lanières 5 min à feu vif.\nAjouter les légumes émincés 4 min, puis les nouilles et la sauce soja."},{"n":"Dinde au paprika, patate douce et haricots verts","t":35,"g":["volaille","healthy"],"i":[["Escalopes de dinde",300,"g"],["Patates douces",2,"pièce"],["Haricots verts",200,"g"],["Paprika"]],"e":"Rôtir les patates douces en cubes 25 min à 200 °C.\nCuire les haricots verts 8 min.\nSaisir la dinde saupoudrée de paprika 4 min par face."},{"n":"Émincé de dinde aux champignons et riz","t":25,"g":["volaille","healthy"],"i":[["Escalopes de dinde",300,"g"],["Champignons",250,"g"],["Crème légère",100,"mL"],["Riz basmati",150,"g"],["Oignon",1,"pièce"]],"e":"Cuire le riz.\nSaisir la dinde en lanières, réserver.\nFaire revenir l'oignon et les champignons 6 min, remettre la dinde et la crème, 2 min."},{"n":"Saumon au four, quinoa et asperges","t":25,"g":["poisson","healthy"],"i":[["Pavés de saumon",2,"pièce"],["Quinoa",150,"g"],["Asperges vertes",250,"g"],["Citron",1,"pièce"]],"e":"Cuire le quinoa.\nDisposer saumon et asperges sur une plaque avec citron et huile.\nCuire 15 min à 200 °C."},{"n":"Saumon en croûte d'herbes et haricots verts","t":25,"g":["poisson","healthy"],"i":[["Pavés de saumon",2,"pièce"],["Haricots verts",300,"g"],["Moutarde"],["Persil"],["Chapelure"]],"e":"Badigeonner le saumon de moutarde, couvrir de persil et de chapelure.\nCuire 15 min à 200 °C.\nCuire les haricots verts 8 min à l'eau."},{"n":"Cabillaud et purée de brocoli","t":30,"g":["poisson","healthy"],"i":[["Filets de cabillaud",300,"g"],["Brocoli",1,"pièce"],["Pommes de terre",2,"pièce"],["Citron",1,"pièce"]],"e":"Cuire le brocoli et les pommes de terre 20 min, écraser en purée.\nPoêler le cabillaud 3 min par face, arroser de citron."},{"n":"Colin à la provençale et riz","t":30,"g":["poisson","healthy"],"i":[["Filets de colin",300,"g"],["Tomates concassées",1,"boîte"],["Courgette",1,"pièce"],["Riz basmati",150,"g"],["Oignon",1,"pièce"],["Herbes de Provence"]],"e":"Faire revenir l'oignon et la courgette en dés, ajouter les tomates, 10 min.\nDéposer le colin dans la sauce, couvrir et cuire 8 min.\nServir avec le riz."},{"n":"Crevettes à l'ail, courgettes et quinoa","t":20,"g":["poisson","healthy","rapide"],"i":[["Crevettes décortiquées",250,"g"],["Courgettes",2,"pièce"],["Quinoa",150,"g"],["Citron",1,"pièce"],["Ail"]],"e":"Cuire le quinoa.\nPoêler les courgettes en dés 6 min.\nAjouter les crevettes et l'ail 3 min, arroser de citron."},{"n":"Curry de crevettes au lait de coco","t":25,"g":["poisson","healthy"],"i":[["Crevettes décortiquées",250,"g"],["Lait de coco",1,"boîte"],["Tomates concassées",1,"boîte"],["Riz basmati",150,"g"],["Oignon",1,"pièce"],["Curry"]],"e":"Faire revenir l'oignon avec le curry.\nAjouter tomates et lait de coco, mijoter 10 min.\nAjouter les crevettes 4 min.\nServir avec le riz."},{"n":"Tacos de cabillaud, chou rouge et yaourt","t":25,"g":["poisson","healthy"],"i":[["Filets de cabillaud",300,"g"],["Tortillas complètes",4,"pièce"],["Chou rouge",0.5,"pièce"],["Yaourt grec",1,"pot"],["Citron vert",1,"pièce"],["Mélange épices fajitas",0.5,"sachet"]],"e":"Émincer finement le chou, l'assaisonner de citron vert.\nPoêler le cabillaud avec les épices 6 min, l'émietter.\nGarnir les tortillas de poisson, chou et yaourt."},{"n":"Maquereau rôti, pommes de terre et salade","t":35,"g":["poisson","healthy"],"i":[["Filets de maquereau",2,"pièce"],["Pommes de terre",3,"pièce"],["Salade verte",1,"pièce"],["Citron",1,"pièce"]],"e":"Rôtir les pommes de terre en quartiers 25 min à 200 °C.\nAjouter les maquereaux les 8 dernières minutes.\nServir avec la salade et le citron."},{"n":"Tartines de sardines, tomates et salade","t":10,"g":["poisson","healthy","rapide"],"i":[["Sardines",1,"boîte"],["Pain complet",4,"tranche"],["Tomates",2,"pièce"],["Salade verte",1,"pièce"],["Citron",1,"pièce"]],"e":"Griller le pain.\nÉcraser les sardines avec le citron.\nGarnir les tartines de tomates et de sardines, servir avec la salade."},{"n":"Steak de thon, riz et légumes sautés","t":20,"g":["poisson","healthy","rapide"],"i":[["Steaks de thon",2,"pièce"],["Riz basmati",150,"g"],["Poivron",1,"pièce"],["Courgette",1,"pièce"],["Sauce soja"]],"e":"Cuire le riz.\nSauter les légumes émincés 6 min.\nSaisir le thon 2 min par face, arroser de sauce soja."},{"n":"Bœuf sauté aux poivrons et riz","t":25,"g":["viande","healthy"],"i":[["Émincé de bœuf",300,"g"],["Poivrons",2,"pièce"],["Oignon",1,"pièce"],["Riz basmati",150,"g"],["Sauce soja"]],"e":"Cuire le riz.\nSaisir le bœuf 2 min à feu vif, réserver.\nSauter poivrons et oignon 5 min, remettre le bœuf et la sauce soja."},{"n":"Steak, haricots verts et patate douce rôtie","t":35,"g":["viande","healthy"],"i":[["Steaks de bœuf",2,"pièce"],["Haricots verts",300,"g"],["Patates douces",2,"pièce"]],"e":"Rôtir les patates douces en frites 25 min à 200 °C.\nCuire les haricots verts 8 min.\nCuire les steaks à la poêle selon la cuisson voulue."},{"n":"Boulettes de bœuf à la tomate et pâtes complètes","t":35,"g":["viande","healthy"],"i":[["Viande hachée 5 %",300,"g"],["Pâtes complètes",160,"g"],["Tomates concassées",1,"boîte"],["Oignon",1,"pièce"],["Œufs",1,"pièce"]],"e":"Mélanger la viande avec l'œuf, former des boulettes.\nLes dorer 5 min, ajouter l'oignon et les tomates, mijoter 15 min.\nServir avec les pâtes."},{"n":"Chili con carne léger","t":40,"g":["viande","healthy"],"i":[["Viande hachée 5 %",300,"g"],["Haricots rouges",1,"boîte"],["Tomates concassées",1,"boîte"],["Maïs doux",1,"boîte"],["Oignon",1,"pièce"],["Riz basmati",150,"g"],["Cumin"]],"e":"Faire revenir l'oignon et la viande.\nAjouter le cumin, les tomates, les haricots et le maïs, mijoter 20 min.\nServir avec le riz."},{"n":"Filet mignon à la moutarde et haricots verts","t":35,"g":["viande","healthy"],"i":[["Filet mignon de porc",400,"g"],["Haricots verts",300,"g"],["Pommes de terre",2,"pièce"],["Moutarde"]],"e":"Badigeonner le filet mignon de moutarde, le cuire 25 min à 200 °C.\nCuire les pommes de terre et les haricots verts à l'eau.\nTrancher et servir."},{"n":"Poulet tandoori, raïta et boulgour","t":30,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Yaourt grec",1,"pot"],["Concombre",1,"pièce"],["Boulgour",150,"g"],["Épices tandoori"]],"e":"Mariner le poulet dans la moitié du yaourt et les épices.\nCuire le boulgour.\nPoêler le poulet 10 min.\nMélanger le reste du yaourt et le concombre râpé pour la raïta."},{"n":"Bowl poulet, quinoa et avocat","t":25,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Quinoa",150,"g"],["Avocat",1,"pièce"],["Tomates cerises",150,"g"],["Maïs doux",1,"boîte"],["Citron vert",1,"pièce"]],"e":"Cuire le quinoa.\nGriller le poulet et le couper en lanières.\nDresser les bols avec l'avocat, les tomates et le maïs, arroser de citron vert."},{"n":"Papillote de saumon aux poireaux","t":30,"g":["poisson","healthy"],"i":[["Pavés de saumon",2,"pièce"],["Poireaux",2,"pièce"],["Pommes de terre",3,"pièce"],["Crème légère",50,"mL"]],"e":"Faire fondre les poireaux émincés 10 min.\nDisposer poireaux, saumon et crème en papillotes, cuire 15 min à 200 °C.\nServir avec les pommes de terre vapeur."},{"n":"Lieu noir sauce vierge et riz","t":25,"g":["poisson","healthy"],"i":[["Filets de lieu noir",300,"g"],["Tomates",2,"pièce"],["Citron",1,"pièce"],["Riz basmati",150,"g"],["Basilic"],["Huile d'olive"]],"e":"Cuire le riz.\nCouper les tomates en petits dés, mélanger avec huile, citron et basilic.\nPoêler le poisson 3 min par face, napper de sauce vierge."},{"n":"Salade de crevettes, avocat et pamplemousse","t":15,"g":["poisson","healthy","rapide"],"i":[["Crevettes décortiquées",200,"g"],["Avocat",1,"pièce"],["Pamplemousse",1,"pièce"],["Salade verte",1,"pièce"]],"e":"Peler le pamplemousse à vif et le couper en suprêmes.\nCouper l'avocat.\nAssembler avec la salade et les crevettes."},{"n":"Poulet au basilic thaï","t":20,"g":["volaille","healthy","rapide"],"i":[["Escalopes de poulet",300,"g"],["Haricots verts",200,"g"],["Riz basmati",150,"g"],["Sauce soja"],["Basilic"],["Ail"]],"e":"Cuire le riz.\nSaisir le poulet haché au couteau avec l'ail 5 min.\nAjouter les haricots verts coupés et la sauce soja, 5 min, puis le basilic."},{"n":"Escalopes de dinde panées au four, purée de carottes","t":35,"g":["volaille","healthy"],"i":[["Escalopes de dinde",300,"g"],["Carottes",4,"pièce"],["Pommes de terre",1,"pièce"],["Œufs",1,"pièce"],["Chapelure"]],"e":"Passer la dinde dans l'œuf battu puis la chapelure, cuire 20 min à 200 °C.\nCuire carottes et pomme de terre 20 min, mixer en purée."},{"n":"Gratin de cabillaud aux épinards","t":35,"g":["poisson","healthy"],"i":[["Filets de cabillaud",300,"g"],["Épinards frais",300,"g"],["Crème légère",100,"mL"],["Emmental râpé",40,"g"],["Riz basmati",150,"g"]],"e":"Faire tomber les épinards.\nDisposer épinards et cabillaud dans un plat, napper de crème, parsemer d'emmental.\nCuire 20 min à 200 °C.\nServir avec le riz."}]$j$::jsonb d),
foyer as (select id from foyers order by cree_le limit 1),
src as (select e from data, jsonb_array_elements(d) e),
ins as (
  insert into recettes (foyer_id, nom, portions, temps_min, etapes, tags, source)
  select foyer.id, e->>'n', 2, (e->>'t')::int, e->>'e', array(select jsonb_array_elements_text(e->'g')), 'claude'
  from src, foyer where not exists (select 1 from recettes r where r.foyer_id = foyer.id and r.nom = e->>'n')
  returning id, nom
)
insert into recette_ingredients (recette_id, nom, quantite, unite, ordre)
select ins.id, i.v->>0, (i.v->>1)::numeric, i.v->>2, i.n - 1
from ins join src on src.e->>'n' = ins.nom
cross join lateral jsonb_array_elements(src.e->'i') with ordinality as i(v, n);
